// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;

    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint256 currentTime, uint256 unlockTime, address actor) public {
        vm.assume(actor != address(0));
        currentTime = bound(currentTime, 1, 2 ** 128);
        unlockTime = bound(unlockTime, 0, 2 ** 128);
        vm.warp(currentTime);

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.Put{value: 1 ether}(unlockTime);

        assertTrue(__invmut_c_Acc_unlockTime(actor) >= currentTime);
    }

    function __invmut_c_Acc_unlockTime(address __k) internal view returns (uint256) {
        (uint256 _v0, ) = c.Acc(__k);
        return _v0;
    }
}
